OUT.mkdir(exist_ok=True)
story = (HERE / "STORYBOARD.md").read_text(encoding="utf-8")
rows = [line.split("|")[1:-1] for line in story.splitlines() if re.match(r"^\| \d+ \|", line)]
rows = [[part.strip() for part in row] for row in rows]
