chapters = ["현장의 필요", "연구 질문", "학습과 평가", "MVP 성과", "남은 과제", "다음 걸음"]
def chapter(n):
    return 0 if n <= 5 else 1 if n <= 10 else 2 if n <= 17 else 3 if n <= 25 else 4 if n <= 27 else 5

def slot(label, detail="실제 자료 선정 후 배치", cls=""):
    return f'<div class="media-slot {cls}"><span class="slot-tag">자료 자리</span><div><span class="playmark">▷</span><h3>{label}</h3><p>{detail}</p></div><span class="slot-corner">실제 결과·제품 이미지 사용</span></div>'

def heading(kicker, title, sub=""):
    return f'<header class="slide-head"><div class="eyebrow">{kicker}</div><h1>{title}</h1>{f"<p>{sub}</p>" if sub else ""}</header>'

def bars(values, labels, note="", colors=None):
    colors = colors or ["#657181", "#0e7a6e", "#0e7a6e"]
    body = ''.join(f'<div class="bar-row"><span>{lab}</span><div class="bar-track"><i style="width:{val}%;background:{col}"></i></div><strong>{val:.1f}<small>%</small></strong></div>' for val, lab, col in zip(values, labels, colors))
    return f'<div class="bars">{body}<div class="bar-scale"><span>0</span><span>50</span><span>100%</span></div></div><p class="evidence">{note}</p>'

def step(label, sub="", cls=""):
    return f'<div class="step {cls}"><strong>{label}</strong><span>{sub}</span></div>'

def flow(items):
    return '<div class="flow">' + '<span class="connector" aria-hidden="true">→</span>'.join(step(*x) if isinstance(x, tuple) else step(x) for x in items) + '</div>'

def split(a,b,cls=""):
    return f'<div class="split {cls}"><div>{a}</div><div>{b}</div></div>'

