for n, title, message, visual, bridge in rows:
    i = int(n)
    slides.append(f'<section class="slide {"dark" if i in [1,8,10,34] else ""}" id="slide-{i}" aria-label="{i}. {html.escape(title)}" aria-hidden="true">{content[i]}<span class="print-number">{i:02} / 34 · FOOTHOLD 구성 초안</span></section>')
metadata = [{'n':int(n), 'title':title, 'message':message, 'visual':visual, 'bridge':bridge, 'chapter':chapter(int(n))} for n,title,message,visual,bridge in rows]
js = r'''
const DATA=__DATA__, chapters=__CHAPTERS__;
const slides=[...document.querySelectorAll('.slide')], deck=document.querySelector('#deck'), notes=document.querySelector('#notes'), overview=document.querySelector('#overview'), blank=document.querySelector('#blank');
let current=0, digits='', digitTimer;
function resize(){deck.style.transform=`translate(-50%,-50%) scale(${Math.min(innerWidth/1600,innerHeight/900)})`;}
function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i!==current)});location.hash=String(current+1);document.querySelector('#count').textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;const dark=slides[current].classList.contains('dark');document.querySelector('#footer').classList.toggle('dark-foot',dark);document.querySelector('.draft').classList.toggle('on-dark',dark);document.querySelectorAll('#progress button').forEach((b,i)=>{b.classList.toggle('current',i===DATA[current].chapter);b.classList.toggle('done',i<DATA[current].chapter);if(i===DATA[current].chapter)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});document.querySelector('#note-title').textContent=`${current+1}. ${DATA[current].title}`;for(const k of ['message','visual','bridge'])document.querySelector('#note-'+k).textContent=DATA[current][k];document.querySelectorAll('.overview-item').forEach((b,i)=>b.classList.toggle('selected',i===current));}
function toggleNotes(){notes.hidden=!notes.hidden;}
function toggleOverview(){overview.hidden=!overview.hidden;if(!overview.hidden)document.querySelector('.overview-item.selected')?.focus();}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.querySelector('#hint').textContent='전체화면을 사용할 수 없습니다. 브라우저 F11을 이용하세요.';}}
document.querySelector('#progress').innerHTML=chapters.map((x,i)=>`<button type="button" data-chapter="${i}" title="${x}">__SYMBOL__<span>${x}</span></button>`).join('');
document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>show(DATA.findIndex(x=>x.chapter===Number(b.dataset.chapter))));
document.querySelector('#overview-grid').innerHTML=DATA.map(x=>`<button type="button" class="overview-item" data-slide="${x.n-1}"><span>${String(x.n).padStart(2,'0')} · ${chapters[x.chapter]}</span><strong>${x.title}</strong></button>`).join('');
document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{show(Number(b.dataset.slide));overview.hidden=true});
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{({prev:()=>show(current-1),next:()=>show(current+1),overview:toggleOverview,notes:toggleNotes,fullscreen,closeNotes:()=>notes.hidden=true,closeOverview:()=>overview.hidden=true}[b.dataset.action])()});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){notes.hidden=true;overview.hidden=true;blank.hidden=true;return}if(e.key.toLowerCase()==='b'){blank.hidden=!blank.hidden;return}if(!blank.hidden){blank.hidden=true;return}if(e.key.toLowerCase()==='g'){e.preventDefault();toggleOverview();return}if(e.key.toLowerCase()==='n'){toggleNotes();return}if(e.key.toLowerCase()==='f'){fullscreen();return}if(!overview.hidden||e.target.closest('input'))return;if(e.target.closest('button,a')&&[' ','Enter'].includes(e.key))return;if(/^\d$/.test(e.key)){digits+=e.key;clearTimeout(digitTimer);digitTimer=setTimeout(()=>digits='',2000);return}if(e.key==='Enter'&&digits){show(Number(digits)-1);digits='';return}if(['ArrowRight','ArrowDown','PageDown',' ','Enter'].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','ArrowUp','PageUp','Backspace'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home'){e.preventDefault();show(0)}if(e.key==='End'){e.preventDefault();show(slides.length-1)}});
deck.addEventListener('click',e=>{if(e.target.closest('a,button')||!notes.hidden)return;const r=deck.getBoundingClientRect(),x=(e.clientX-r.left)/r.width;if(x>.8)show(current+1);else if(x<.12)show(current-1)});
let touchStart=null;deck.addEventListener('touchstart',e=>{touchStart=e.touches[0].clientX},{passive:true});deck.addEventListener('touchend',e=>{if(touchStart===null)return;let delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>60)show(current+(delta<0?1:-1));touchStart=null},{passive:true});
blank.onclick=()=>blank.hidden=true;window.addEventListener('resize',resize);window.addEventListener('hashchange',()=>{let n=parseInt(location.hash.slice(1));if(Number.isFinite(n)&&n-1!==current)show(n-1)});resize();show((parseInt(location.hash.slice(1))||1)-1);
'''.replace('__DATA__',json.dumps(metadata,ensure_ascii=False)).replace('__CHAPTERS__',json.dumps(chapters,ensure_ascii=False)).replace('__SYMBOL__',symbol.replace('\n',''))
page = f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FOOTHOLD MVP · 전체 레이아웃 초안</title><style>{font}\n{css}</style></head><body><main id="viewport"><div id="deck">{''.join(slides)}<span class="draft">구성 초안 · 자료 선정 중</span><footer id="footer"><nav id="progress" aria-label="발표 구간"></nav><span id="count" aria-live="polite"></span></footer></div></main><div id="toolbar"><button data-action="prev" title="이전 화면">←</button><button data-action="next" title="다음 화면">→</button><button data-action="overview">G 전체보기</button><button data-action="notes">N 검토 메모</button><button data-action="fullscreen">F 전체화면</button></div><div id="hint">← → 화면 이동 · G 전체보기 · N 메모 · F 전체화면 · B 가림 · 숫자+Enter 이동</div><aside id="notes" hidden><button data-action="closeNotes" aria-label="메모 닫기">×</button><h2 id="note-title"></h2><h3>전달할 핵심</h3><p id="note-message"></p><h3>필요한 자료와 조건</h3><p id="note-visual"></p><h3>다음 화면으로 연결</h3><p id="note-bridge"></p><h3>검토 기준</h3><p>흐름 · 한눈에 읽히는 핵심 · 자료의 크기와 위치를 확인하는 초안입니다. 자료 자리는 실제 결과를 의미하지 않습니다.</p></aside><div id="overview" hidden><button data-action="closeOverview" aria-label="전체보기 닫기">×</button><h2>FOOTHOLD · 전체 흐름</h2><div id="overview-grid"></div></div><div id="blank" hidden aria-label="검은 화면"></div><script>{js}</script></body></html>'''
assert '\u2014' not in page
(OUT / 'FOOTHOLD-MVP-layout.html').write_text(page,encoding='utf-8')
print(f'Built {len(rows)} slides · {len(page.encode("utf-8")):,} bytes')
